import{_ as e,o as a,c as s,ae as i}from"./chunks/framework.RRduUuAx.js";const k=JSON.parse('{"title":"Philosophy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/philosophy.md","filePath":"guide/philosophy.md"}'),r={name:"guide/philosophy.md"};function o(n,t,p,d,h,l){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="philosophy" tabindex="-1">Philosophy <a class="header-anchor" href="#philosophy" aria-label="Permalink to &quot;Philosophy&quot;">​</a></h1><h2 id="why-trapi" tabindex="-1">Why TRAPI? <a class="header-anchor" href="#why-trapi" aria-label="Permalink to &quot;Why TRAPI?&quot;">​</a></h2><p>Libraries like <a href="https://github.com/lukeautry/tsoa" target="_blank" rel="noreferrer">tsoa</a> pioneered the idea of extracting OpenAPI specifications from TypeScript decorators. TRAPI shares that vision but takes a fundamentally different approach: <strong>decorator-framework agnosticism</strong>.</p><p>Most TypeScript REST frameworks — Express with decorators, typescript-rest, routing-controllers — define their own decorator sets. Each framework&#39;s decorators carry the same semantic meaning (<code>@Get()</code>, <code>@Post()</code>, <code>@Body()</code>, <code>@Query()</code>), but with different names, import paths, and conventions. tsoa solves this by shipping its own decorator set that you must adopt. TRAPI solves it by letting you <strong>map any decorator set</strong> to a shared metadata model.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><h3 id="_1-bring-your-own-decorators" tabindex="-1">1. Bring Your Own Decorators <a class="header-anchor" href="#_1-bring-your-own-decorators" aria-label="Permalink to &quot;1. Bring Your Own Decorators&quot;">​</a></h3><p>TRAPI does not force you to adopt a specific decorator library. Instead, you define a <strong>decorator mapping</strong> — a configuration that tells TRAPI which decorator in your codebase corresponds to which semantic concept (controller, HTTP method, parameter source, etc.).</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Example: mapping @decorators/express to TRAPI&#39;s metadata model</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    [DecoratorID.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CONTROLLER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: { name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Controller&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    [DecoratorID.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: { name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Get&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    [DecoratorID.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: { name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Post&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    [DecoratorID.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">BODY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]: { name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Body&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This means any HTTP framework built on TypeScript decorators can get metadata extraction and OpenAPI generation for free — without changing a single line of application code.</p><h3 id="_2-pure-ast-analysis" tabindex="-1">2. Pure AST Analysis <a class="header-anchor" href="#_2-pure-ast-analysis" aria-label="Permalink to &quot;2. Pure AST Analysis&quot;">​</a></h3><p>TRAPI extracts metadata entirely through <strong>static analysis</strong> of the TypeScript AST. Decorators are no-ops at runtime — they exist only as markers for the compiler API to read. There is no dependency on <code>reflect-metadata</code> or runtime type information.</p><p>This has several advantages:</p><ul><li><strong>Zero runtime overhead</strong> — decorators add no behavior to your application</li><li><strong>Build-time safety</strong> — metadata errors are caught during generation, not at runtime</li><li><strong>Framework independence</strong> — works with any TypeScript version and any decorator style</li></ul><h3 id="_3-separation-of-concerns" tabindex="-1">3. Separation of Concerns <a class="header-anchor" href="#_3-separation-of-concerns" aria-label="Permalink to &quot;3. Separation of Concerns&quot;">​</a></h3><p>The pipeline is split into independent, composable packages:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Package</th><th>Responsibility</th></tr></thead><tbody><tr><td>Core</td><td><code>@trapi/metadata</code></td><td>Extract metadata from TypeScript source</td></tr><tr><td>Output</td><td><code>@trapi/swagger</code></td><td>Transform metadata into OpenAPI specs</td></tr><tr><td>Mapping</td><td><code>@trapi/decorators</code></td><td>Default decorator set and mapping</td></tr><tr><td>Presets</td><td><code>@trapi/preset-*</code></td><td>Framework-specific decorator mappings</td></tr></tbody></table><p>Each layer can be used independently. You can use <code>@trapi/metadata</code> alone to power custom code generators, route validators, or documentation tools — the metadata representation is not tied to OpenAPI.</p><h3 id="_4-typescript-compiler-as-the-source-of-truth" tabindex="-1">4. TypeScript Compiler as the Source of Truth <a class="header-anchor" href="#_4-typescript-compiler-as-the-source-of-truth" aria-label="Permalink to &quot;4. TypeScript Compiler as the Source of Truth&quot;">​</a></h3><p>Rather than inventing a parallel type system or requiring JSDoc annotations for everything, TRAPI leverages the TypeScript compiler&#39;s own type checker. When you write:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;status&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) status: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;active&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;inactive&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">): </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Promise</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">User[]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span></code></pre></div><p>TRAPI resolves <code>&#39;active&#39; | &#39;inactive&#39;</code> and <code>Promise&lt;User[]&gt;</code> through the same type checker that powers your IDE. Generics, utility types (<code>Partial&lt;T&gt;</code>, <code>Pick&lt;T, K&gt;</code>), intersections, mapped types — they all resolve through TypeScript itself, not through a reimplemented type system.</p><h2 id="trapi-vs-tsoa" tabindex="-1">TRAPI vs tsoa <a class="header-anchor" href="#trapi-vs-tsoa" aria-label="Permalink to &quot;TRAPI vs tsoa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>TRAPI</th><th>tsoa</th></tr></thead><tbody><tr><td>Decorator source</td><td>Any framework&#39;s decorators (via presets)</td><td>tsoa&#39;s own decorators only</td></tr><tr><td>Runtime behavior</td><td>Decorators are no-ops</td><td>Decorators are no-ops</td></tr><tr><td>Type resolution</td><td>TypeScript compiler API</td><td>TypeScript compiler API</td></tr><tr><td>Output</td><td>OpenAPI 2.0 / 3.0</td><td>OpenAPI 2.0 / 3.0 / 3.1</td></tr><tr><td>Route generation</td><td>No (metadata only)</td><td>Yes (generates Express/Koa/Hapi routes)</td></tr><tr><td>Runtime validation</td><td>No (build-time only)</td><td>Yes (validates requests at runtime)</td></tr><tr><td>Framework lock-in</td><td>None</td><td>Must use tsoa decorators</td></tr></tbody></table><p>TRAPI intentionally does <strong>not</strong> generate route handlers or perform runtime validation. These are orthogonal concerns best handled by the HTTP framework you already chose. TRAPI focuses on doing one thing well: turning your decorated TypeScript into accurate API metadata and specifications.</p><h2 id="when-to-use-trapi" tabindex="-1">When to Use TRAPI <a class="header-anchor" href="#when-to-use-trapi" aria-label="Permalink to &quot;When to Use TRAPI&quot;">​</a></h2><p>TRAPI is the right choice when:</p><ul><li>You already use a decorator-based HTTP framework and want OpenAPI docs without adopting a new decorator set</li><li>You want metadata extraction as a build step, not a runtime dependency</li><li>You need to support multiple frameworks with the same tooling</li><li>You want the metadata for purposes beyond OpenAPI (custom generators, validators, SDK generation)</li></ul><p>If you need an all-in-one solution that handles routing, validation, and documentation from a single decorator set, tsoa is a great choice. TRAPI is for teams that want to keep those concerns separate.</p>`,28)])])}const y=e(r,[["render",o]]);export{k as __pageData,y as default};
